using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDayAPI.Data;using RaceDayAPI.Models;using System.Security.Claims;namespace RaceDayAPI.Controllers{    [Route("api/[controller]")]    [ApiController]    public class EnrolmentsController : ControllerBase    {        private readonly RaceDayDbContext _context;        public EnrolmentsController(RaceDayDbContext context)        {            _context = context;        }        // POST: /api/enrolments (Participant only)        [HttpPost]        [Authorize(Roles = "Participant")]        public async Task<IActionResult> CreateEnrolment([FromBody] EnrolmentDto dto)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var participant = await _context.Participants.FirstOrDefaultAsync(p => p.UserID == userId);            if (participant == null) return Forbid();            var exists = await _context.Enrolments                .AnyAsync(e => e.ParticipantID == participant.ParticipantID && e.EventID == dto.EventID);            if (exists) return Conflict("Already enrolled in this event.");            var category = await _context.Categories.FirstOrDefaultAsync(c => c.CategoryID == dto.CategoryID);            if (category == null || category.EventID != dto.EventID)                return BadRequest("Invalid category for this event.");            var enrolment = new Enrolment            {                ParticipantID = participant.ParticipantID,                EventID = dto.EventID,                CategoryID = dto.CategoryID,                Status = "Registered"            };            _context.Enrolments.Add(enrolment);            await _context.SaveChangesAsync();            return Ok(enrolment);        }        // GET: /api/enrolments/me (Participant)        [HttpGet("me")]        [Authorize(Roles = "Participant")]        public async Task<IActionResult> GetMyEnrolments()        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var participant = await _context.Participants.FirstOrDefaultAsync(p => p.UserID == userId);            if (participant == null) return Forbid();            var enrolments = await _context.Enrolments                .Include(e => e.Event)                .Include(e => e.Category)                .Where(e => e.ParticipantID == participant.ParticipantID)                .ToListAsync();            return Ok(enrolments);        }        // GET: /api/enrolments/event/{eventId} (Organiser owner)        [HttpGet("event/{eventId}")]        [Authorize(Roles = "Organiser")]        public async Task<IActionResult> GetEnrolmentsForEvent(int eventId)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var organiser = await _context.Organisers.FirstOrDefaultAsync(o => o.UserID == userId);            if (organiser == null) return Forbid();            var ev = await _context.Events.FirstOrDefaultAsync(e => e.EventID == eventId);            if (ev == null) return NotFound();            if (ev.OrganiserID != organiser.OrganiserID) return Forbid();            var enrolments = await _context.Enrolments                .Include(e => e.Participant).ThenInclude(p => p.User)                .Include(e => e.Category)                .Where(e => e.EventID == eventId)                .ToListAsync();            return Ok(enrolments);        }    }    public class EnrolmentDto    {        public int EventID { get; set; }        public int CategoryID { get; set; }    }}